    (v_aula_id, 1, $p$Keller mostra que todo pecado tem uma tempestade vinculada a si, embora nem toda tempestade seja castigo por pecado; que "tempestade" na sua vida hoje você tem evitado examinar com sinceridade diante de Deus?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$O texto diz que, ao edificarmos sentido em algo que não seja Deus, agimos contra o próprio desígnio do nosso ser; sobre o que você tem construído sua identidade que está, aos poucos, te atacando de volta?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Jonas fugiu da grande cidade e caiu na grande tempestade; em que ponto você reconhece que sua resistência a obedecer a Deus tem gerado consequências que você prefere atribuir ao acaso?$p$, 'reflexao', null);
  end if;

  select id into v_aula_id from public.aulas where curso_id = v_curso_id and ordem = 4;
