    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$Jesus se chama "maior do que Jonas": Jonas foi sacrificado por seus próprios pecados, mas Jesus morreu pelos seus; quando você contempla que Aquele que não tinha culpa tomou seu lugar, o que muda no modo como você enxerga seus próprios fracassos?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Keller mostra que Jonas foi apenas uma sombra do verdadeiro substituto; em que momentos você ainda tenta ser o seu próprio salvador, carregando culpas que Jesus já se ofereceu para carregar por você?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Se o sacrifício de um homem já podia salvar marinheiros, quanto mais o sacrifício do Filho de Deus; de que forma essa verdade confronta a frieza ou o ressentimento que você nutre por alguém a quem Cristo também morreu para salvar?$p$, 'reflexao', null);
